$spent = 0.0; $out = @(); $i = 0
foreach ($k in $t.Keys) { $i++
  $body = @{ subject=$t[$k]; model="gpt-image-2"; width=1024; height=1024; exact_size=$true; raw=$true } | ConvertTo-Json -Compress
  $line = ""; for ($try = 1; $try -le 2 -and -not $line; $try++) {
    try { $j = (RUN ("SHOW_IT " + $body)) | ConvertFrom-Json
      if ($j.payload.ok -and $j.payload.id) { $spent += [double]$j.payload.cost_usd; $line = $k + " -> " + $j.payload.id } elseif ($try -eq 2) { $line = $k + " -> NOT DRAWN: " + $j.payload.error } } catch { if ($try -eq 2) { $line = $k + " -> NOT DRAWN: " + $_.Exception.Message } } }
  "  " + $i + "/" + $t.Count + " " + $line; $out += $line }
$out += ("== spent: $" + [math]::Round($spent, 3)); Set-Content -Encoding utf8 -Path .\lettering-tiles-result.txt -Value $out
"== spent this run: $" + [math]::Round($spent, 3) + " - saved to lettering-tiles-result.txt"
